#nullable enable // autogenerated

using MVZ2.Managers;
using PVZEngine;

namespace MVZ2.Resources
{
    public class BaseGameFragmentSourceProvider : BaseGameResourceProvider, IFragmentSourceProvider
    {
        public BaseGameFragmentSourceProvider(ResourceManager resources, int priority = 0) : base(resources, priority)
        {
        }
        public bool TryGet(NamespaceID id, out IFragmentSource? resource)
        {
            resource = Resources.GetFragmentMeta(id);
            return resource != null;
        }
    }
}
